from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        z=(y+dy,x+dx)
                        if 0<=z[0]<h and 0<=z[1]<w and grid[z[0]][z[1]] and z not in seen:
                            seen.add(z);q.append(z)
                comps.append(comp)
    src=max(comps,key=len)
    r0=min(r for r,c in src); r1=max(r for r,c in src)
    c0=min(c for r,c in src); c1=max(c for r,c in src)
    pat=[[grid[r][c] if (r,c) in set(src) else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    markers=[comp[0] for comp in comps if comp is not src and len(comp)==1]
    out=[[0]*w for _ in range(h)]
    for mr,mc in markers:
        for dy,row in enumerate(pat):
            for dx,v in enumerate(row):
                rr,cc=mr-1+dy,mc-1+dx
                if v and 0<=rr<h and 0<=cc<w: out[rr][cc]=v
    return out

