# Candidate: preserve the 3x3 stamp geometry relative to its center instead of re-centering each row.
def rigid_transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            q=deque([(r,c)]);seen.add((r,c));comp=[]
            while q:
                y,x=q.popleft();comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=bg and (yy,xx) not in seen:
                        seen.add((yy,xx));q.append((yy,xx))
            comps.append(comp)
    shape=max(comps,key=len); r0=min(r for r,c in shape);r1=max(r for r,c in shape);c0=min(c for r,c in shape);c1=max(c for r,c in shape)
    anchors=[co[0] for co in comps if co is not shape and len(co)==1]+[((r0+r1)//2,(c0+c1)//2)]
    out=[[bg]*w for _ in range(h)]
    for ar,ac in anchors:
        for r,c in shape:
            rr=ar+(r-(r0+r1)//2);cc=ac+(c-(c0+c1)//2)
            if 0<=rr<h and 0<=cc<w:out[rr][cc]=grid[r][c]
    return out
